using System.Configuration;

public class DatabaseSettings
{
    // ConfigurationManager reads from Web.config / App.config at runtime.
    // Neither the assembly nor the XML file exist in a .NET 10 project.
    public static string GetConnectionString()
    {
        return ConfigurationManager.ConnectionStrings["Default"].ConnectionString;
    }

    public static int GetPageSize()
    {
        var raw = ConfigurationManager.AppSettings["Paging:PageSize"];
        return int.TryParse(raw, out var n) ? n : 20;
    }

    public static string GetApiKey()
    {
        // Often stored as plain text in Web.config in Framework projects.
        // In .NET 10 this should be in appsettings.json with
        // environment-variable override or a secrets manager.
        return ConfigurationManager.AppSettings["ExternalApi:Key"] ?? "";
    }
}
